def compute(vars):
    change = vars["v1"] - vars["v2"]
    return {
        "value": change,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
